changeSet.sql:
CREATE TABLE permissions ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
code varchar(255) NOT NULL UNIQUE, description varchar(255) NOT NULL,
PRIMARY KEY (id) );

changeSet.rollback:
DELETE FROM permissions WHERE code IN (
    'admin.dashboard.view', 'admin.tenants.view', 'admin.tenants.manage', 'admin.marketplace.conflicts',
    'client.dashboard.view', 'client.marketplace.view', 'client.estates.view', 'client.resale.view',
    'client.portfolio.view', 'client.documents.view', 'client.inspections.view', 'client.enquiries.view',
    'client.syndicates.view', 'client.support.view', 'client.settings.view'
);
